@testable import Screens

struct MemberViewTests {
    @Test("member-view is refused to someone signed in without members.read")
    func refused() {
        #expect(Access.decide(permission: memberViewSchema.permission, session: Session(signedIn: true, permissions: [])) == .refused)
    }

    @Test("member-view sends someone signed out to sign in")
    func signIn() {
